INSERT INTO _migration_585_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_agric_b003_007', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'In any ecosystem, the largest amount of energy is available to the', 'multiple_choice', NULL, '["A. primary consumers","B. secondary consumers","C. producers","D. decomposers"]', 'C', 'Energy enters the ecosystem through producers (green plants) by photosynthesis, and only about 10% of the energy at each trophic level is transferred to the next — the rest is lost as heat and in life processes — so energy decreases up the food chain and producers hold the largest share. Therefore the correct answer is C: producers.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_agric_b003_008', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Bush burning is discouraged as a land-clearing method mainly because it', 'multiple_choice', NULL, '["A. adds excess nitrogen to the soil","B. makes the soil too fertile for crops","C. increases the humus content of the soil","D. destroys soil organic matter and kills beneficial soil organisms"]', 'D', 'Bush burning destroys humus and kills earthworms, microbes and other beneficial organisms, lowering soil fertility and structure; the ash gives only a short-lived mineral boost. It removes rather than adds nitrogen, since nitrogen compounds escape into the air as gases during burning. Therefore the correct answer is D: destroys soil organic matter and kills beneficial soil organisms.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_agric_b003_009', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A rectangular maize farm measures 120 m by 80 m. Calculate the area of the farm in hectares. (1 hectare = 10,000 m²)', 'calculation', NULL, NULL, '0.96 hectares', 'Area = length × width = 120 m × 80 m = 9,600 m². Converting to hectares: 9,600 ÷ 10,000 = 0.96. Answer: the farm covers 0.96 hectares.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_agric_b003_010', 'topic_wassce_intsci_agric', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A school farm keeps a small grassland plot as a study site.', 'structured', NULL, NULL, '(a) An ecosystem is a community of living organisms interacting with one another and with their non-living physical environment, such as soil, water and air. (b) For example, grass → grasshopper → lizard (or grass → grasscutter → hawk); the arrows point from the organism being eaten to the eater, showing the direction of energy flow. (c) Decomposers such as bacteria and fungi break down dead organisms and waste products, releasing nutrients back into the soil for producers to reuse.', '(a) An ecosystem is a community of living organisms interacting with one another and with their non-living physical environment, such as soil, water and air. (b) For example, grass → grasshopper → lizard (or grass → grasscutter → hawk); the arrows point from the organism being eaten to the eater, showing the direction of energy flow. (c) Decomposers such as bacteria and fungi break down dead organisms and waste products, releasing nutrients back into the soil for producers to reuse.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL),
('q_wisc_health_b003_001', 'topic_wassce_intsci_health', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following methods is most reliable for killing disease-causing micro-organisms in drinking water at home?', 'multiple_choice', NULL, '["A. Boiling the water","B. Decanting the water","C. Sieving the water through cloth","D. Leaving the water to settle"]', 'A', 'Boiling kills the bacteria, viruses and other pathogens in water. Decanting, sieving and settling only remove suspended particles; they do not kill the micro-organisms that cause diseases such as cholera and typhoid. Therefore the correct answer is A: Boiling the water.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_health_b003_002', 'topic_wassce_intsci_health', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following diseases is commonly spread by houseflies?', 'multiple_choice', NULL, '["A. Malaria","B. Cholera","C. Tuberculosis","D. Measles"]', 'B', 'Houseflies carry germs from faeces and refuse onto food, spreading intestinal diseases such as cholera, typhoid and dysentery. Malaria is spread by mosquitoes, tuberculosis by air-borne droplets, and measles by coughing and sneezing. Therefore the correct answer is B: Cholera.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_585_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_agric_b003_010_a', 'q_wisc_agric_b003_010', 'a', 'Define the term ecosystem.', '2', 'An ecosystem is a community of living organisms interacting with one another and with their non-living physical environment, such as soil, water and air.', '1'),
('sqp_q_wisc_agric_b003_010_b', 'q_wisc_agric_b003_010', 'b', 'Construct a food chain with three trophic levels using organisms found in the grassland.', '2', 'For example, grass → grasshopper → lizard (or grass → grasscutter → hawk); the arrows point from the organism being eaten to the eater, showing the direction of energy flow.', '2'),
('sqp_q_wisc_agric_b003_010_c', 'q_wisc_agric_b003_010', 'c', 'State the role of decomposers in the ecosystem.', '2', 'Decomposers such as bacteria and fungi break down dead organisms and waste products, releasing nutrients back into the soil for producers to reuse.', '3');
INSERT INTO _migration_585_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_585_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_585_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_585_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_585_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_585_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_585_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_585_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_585_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_585_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_585_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_585_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
